head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tag > P > id]<br/>Tag 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 Tag 컴포넌트를 구별할 수 있는 유일값을 설정합니다.",
        "값을 설정하지 않으면 화면 렌더링 과정에서 임의의 ID 값이 설정됩니다.",
        "스크립트에서 해당 컴포넌트에 접근하려면 ID 값을 반드시 설정하여야 합니다.",
        "화면 렌더링 과정에서 config.xml 에 설정된 Scope Variable 값이 ID 에 자동으로 추가됩니다.",
        "스크립트에서는 Scope Variable 이 추가된 ID 가 아닌 원래 설정된 ID 를 사용해야 합니다.",
        "WFrame 환경에서는 렌더링 과정에서 ID 가 변경되므로 CSS 정의 시 id Selector 대신 class Selector 를 사용하여야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}

// 예약어 id 로 인한 오류 발생 여부 확인용 카운터
scwin.gErrCount = 0;
window.addEventListener("error", function () { scwin.gErrCount++; });



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 렌더된 Tag 의 id 속성 / 스크립트 조회 / CSS 적용 확인
scwin.btn_getId_onclick = function (e) {
    let elComp = document.querySelector("[id$='grp_comp']");
    let elTarget = elComp.children[1];
    let elAuto = elComp.children[2];
    let elButton = document.querySelector("[id$='btn_getId']");
    let objTarget = $p.getComponentById("target1");
    let objScoped = $p.getComponentById("mf_target1");
    let style1 = window.getComputedStyle(elTarget);
    let objBottom = wf_body_bottom.getObj("scwin");

    // validation 1, 3 판정 출력
    objBottom.setReturnValue("id 설정 - 렌더된 id : " + elTarget.id + " , 설정 ID(target1) 로 컴포넌트 조회 : " + (objTarget ? objTarget.id : "실패"));
    // validation 2 판정 출력
    objBottom.setReturnValue("id 미설정 - 자동 부여된 id : " + (elAuto.id === "" ? "(없음)" : elAuto.id));
    // validation 4 판정 출력
    objBottom.setReturnValue("Scope 적용 - Tag 의 렌더 id : " + elTarget.id + " , 비교용 button(btn_getId) 의 렌더 id : " + elButton.id);
    // validation 5 판정 출력
    objBottom.setReturnValue("원래 ID(target1) 로 조회 : " + (objTarget ? "성공" : "실패") + " , Scope 추가 ID(mf_target1) 로 조회 : " + (objScoped ? "성공" : "실패"));
    // validation 6 판정 출력
    objBottom.setReturnValue("CSS 적용 - id Selector(#target1) border : " + style1.border + " , class Selector(.tagIdClass) border-radius : " + style1.borderRadius);
};



// 예약어(style) 를 id 로 설정한 Tag 의 렌더 결과와 오류 발생 여부 확인
scwin.btn_getReservedId_onclick = function (e) {
    let elReserved = document.querySelector("[id$='grp_comp']").children[3];

    // validation 7 판정 출력
    wf_body_bottom.getObj("scwin").setReturnValue("예약어(style) id 설정 - 렌더된 id : " + elReserved.id + " , 페이지 로드 후 발생한 JS 오류 건수 : " + scwin.gErrCount);
};
